// Ordered byte-granular buffer copies, including native GPU-generated bytes. No upload shadow fallback.
export class WebGPUBufferCopy {
  private pipeline?: GPUComputePipeline;
  constructor(private device: GPUDevice) {}
  copy(src: GPUBuffer, srcOffset: number, dst: GPUBuffer, dstOffset: number, size: number): void {
    const d = this.device, encoder = d.createCommandEncoder();
    if (src !== dst && !(srcOffset % 4 || dstOffset % 4 || size % 4)) {
      encoder.copyBufferToBuffer(src, srcOffset, dst, dstOffset, size);
      d.queue.submit([encoder.finish()]); return;
    }
    this.pipeline ??= d.createComputePipeline({layout:'auto',compute:{entryPoint:'main',module:d.createShaderModule({code:`
struct Params { source_shift:u32, destination_shift:u32, size:u32, words:u32 };
@group(0) @binding(0) var<storage,read> source:array<u32>;
@group(0) @binding(1) var<storage,read_write> destination:array<u32>;
@group(0) @binding(2) var<uniform> p:Params;
@compute @workgroup_size(64) fn main(@builtin(global_invocation_id) id:vec3u) {
 let word=id.x+id.y*65535u*64u;if(word>=p.words){return;}
 var value=destination[word];
 for(var byte=0u;byte<4u;byte++){
  let at=word*4u+byte;
  if(at>=p.destination_shift && at-p.destination_shift<p.size){
   let s=at-p.destination_shift+p.source_shift;
   let v=(source[s/4u]>>((s%4u)*8u))&255u;
   value=(value&~(255u<<(byte*8u)))|(v<<(byte*8u));
  }
 }
 destination[word]=value;
}`})}});
    const s0=srcOffset-srcOffset%4,d0=dstOffset-dstOffset%4;
    const sn=Math.ceil((size+srcOffset%4)/4)*4,dn=Math.ceil((size+dstOffset%4)/4)*4;
    const input=d.createBuffer({size:sn,usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_DST});
    const output=d.createBuffer({size:dn,usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_SRC|GPUBufferUsage.COPY_DST});
    const params=d.createBuffer({size:16,usage:GPUBufferUsage.UNIFORM,mappedAtCreation:true});
    new Uint32Array(params.getMappedRange()).set([srcOffset%4,dstOffset%4,size,dn/4]);params.unmap();
    encoder.copyBufferToBuffer(src,s0,input,0,sn);encoder.copyBufferToBuffer(dst,d0,output,0,dn);
    const pass=encoder.beginComputePass();pass.setPipeline(this.pipeline);
    pass.setBindGroup(0,d.createBindGroup({layout:this.pipeline.getBindGroupLayout(0),entries:[
      {binding:0,resource:{buffer:input}},{binding:1,resource:{buffer:output}},{binding:2,resource:{buffer:params}},
    ]}));
    const groups=Math.ceil(dn/4/64);pass.dispatchWorkgroups(Math.min(groups,65535),Math.ceil(groups/65535));pass.end();
    encoder.copyBufferToBuffer(output,0,dst,d0,dn);d.queue.submit([encoder.finish()]);
    input.destroy();output.destroy();params.destroy();
  }
}
